/**
 * Whole-document Markdown translation: mask everything a model must not touch, build the prompt,
 * then unmask. Shared by the docs pipeline and the i18n engine's `segment: "file"` content spaces.
 *
 * @module
 */

/** One masking pass: what was hidden, and the text with markers in its place. */
interface Masked {
  text: string;
  blocks: string[];
}

function mask(input: string, pattern: RegExp, prefix: string): Masked {
  const blocks: string[] = [];
  const text = input.replace(pattern, (match) => {
    const marker = `__${prefix}_${blocks.length}__`;
    blocks.push(match);
    return marker;
  });
  return { text, blocks };
}

function unmask(input: string, blocks: readonly string[], prefix: string): string {
  let out = input;
  for (const [index, block] of blocks.entries()) {
    out = out.replaceAll(`__${prefix}_${index}__`, block);
  }
  return out;
}

/** Everything masked out of one document, in the order it must be restored. */
export interface PreservedMarkdown {
  text: string;
  codeBlocks: string[];
  inlineCode: string[];
  packageNames: string[];
  escapedBrackets: string[];
  templateTokens: string[];
}

// TypeDoc renders a generic type as several separately backtick-wrapped tokens joined by bare escaped
// angle brackets — the `\<`/`\>` glue sits outside any code span, so it reaches the model as bare
// punctuation and has come back duplicated or mangled. Masking removes the ambiguity.
const ESCAPED_ANGLE_BRACKET = /\\[<>]/g;
// Scaffold templates carry `{{projectName}}`-style tokens that are substituted after translation.
// Excluding "{" from the body (not just "}") keeps this linear on adversarial input like "{{{{...":
// without it, each "{{" start re-scans the same run of braces looking for a close, which is quadratic.
const TEMPLATE_TOKEN = REDACTED;

/** Mask fenced/inline code, package names, escaped angle brackets, and `{{template}}` tokens. */
export function preserveMarkdown(input: string): PreservedMarkdown {
  const fenced = mask(input, /```[\s\S]*?```/g, "PTK_CODE_BLOCK");
  const inline = mask(fenced.text, /`[^`\n]+`/g, "PTK_INLINE_CODE");
  const packages = mask(inline.text, /@[a-z0-9][a-z0-9.-]*\/[a-z0-9][a-z0-9.-]*/gi, "PTK_PACKAGE");
  const brackets = mask(packages.text, ESCAPED_ANGLE_BRACKET, "PTK_ESC");
  const tokens = mask(brackets.text, TEMPLATE_TOKEN, "PTK_VAR");
  return {
    text: tokens.text,
    codeBlocks: fenced.blocks,
    inlineCode: inline.blocks,
    packageNames: packages.blocks,
    escapedBrackets: brackets.blocks,
    templateTokens: tokens.blocks,
  };
}

/** Reverse {@link preserveMarkdown} against a translated document. */
export function restoreMarkdown(translated: string, preserved: PreservedMarkdown): string {
  let out = unmask(translated, preserved.templateTokens, "PTK_VAR");
  out = unmask(out, preserved.escapedBrackets, "PTK_ESC");
  out = unmask(out, preserved.packageNames, "PTK_PACKAGE");
  out = unmask(out, preserved.inlineCode, "PTK_INLINE_CODE");
  return unmask(out, preserved.codeBlocks, "PTK_CODE_BLOCK");
}

const BEGIN = "--- BEGIN MARKDOWN ---";
const END = "--- END MARKDOWN ---";

/** Prompt asking for one masked document back, translated, with its structure intact. */
export function buildMarkdownTranslationPrompt(
  maskedText: string,
  targetLanguage: string,
  reference: string,
): string {
  return [
    `Translate this technical markdown from English to ${targetLanguage}.`,
    "Translate only the content between the BEGIN/END MARKDOWN delimiters.",
    "Return only the translated markdown document body.",
    "Rules:",
    "- Do not include explanations, reasoning, analysis, progress notes, self-corrections, apologies, or alternate attempts.",
    "- Keep markdown structure unchanged.",
    "- Translate heading text too (the words after the leading # symbols) — do not leave headings in English.",
    "- Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__ or __PTK_INLINE_CODE_#__.",
    "- Do not alter placeholder tokens like __PTK_PACKAGE_#__, __PTK_ESC_#__, or __PTK_VAR_#__.",
    "- Preserve whitespace and line breaks.",
    "- Keep import paths, package names, URLs, and identifiers intact.",
    `File: ${reference}`,
    BEGIN,
    maskedText,
    END,
  ].join("\n");
}

const META_COMMENTARY_PATTERNS: readonly RegExp[] = [
  /\bI(?:'ll| will) (?:redo|continue|restart|try again|fix|translate)\b/iu,
  /\b(?:oops|argh)\b/iu,
  /\bdue to time\b/iu,
  /\bmust (?:continue|finish|redo|restart) translation\b/iu,
  /\brestart(?:ing)? (?:from|continuing)\b/iu,
  /\b(?:let's|I need to) (?:produce|finish|continue|redo|restart)\b/iu,
];

const LONG_REPEATED_CHARACTER = /(.)\1{24,}/u;
const HAN_CHARACTER = /\p{Script=Han}/u;
const CJK_TARGET_LANGUAGE = /\b(?:chinese|japanese|korean|cantonese|mandarin|taiwanese)\b/iu;
const TOP_LEVEL_HEADING = /^#[^\S\r\n]+\S.*$/gmu;

/** Throw when an AI response is commentary or corrupted text rather than one translated document. */
export function assertCleanMarkdownTranslation(
  output: string,
  reference: string,
  targetLanguage?: string,
): void {
  for (const pattern of META_COMMENTARY_PATTERNS) {
    if (pattern.test(output)) {
      throw new Error(`Markdown translation for ${reference} contains model commentary`);
    }
  }
  if (LONG_REPEATED_CHARACTER.test(output)) {
    throw new Error(`Markdown translation for ${reference} contains repeated-character garbage`);
  }
  if (targetLanguage && !CJK_TARGET_LANGUAGE.test(targetLanguage) && HAN_CHARACTER.test(output)) {
    throw new Error(`Markdown translation for ${reference} contains unexpected CJK characters`);
  }

  const topLevelHeadings = output.match(TOP_LEVEL_HEADING) ?? [];
  if (topLevelHeadings.length > 1) {
    throw new Error(`Markdown translation for ${reference} contains multiple document starts`);
  }
}

/** Drop the envelope when a model echoes the prompt's delimiters back around its answer. */
export function stripMarkdownEnvelope(output: string): string {
  const start = output.indexOf(BEGIN);
  const finish = output.lastIndexOf(END);
  if (start === -1 || finish <= start) return output;
  return output.slice(start + BEGIN.length, finish).trim();
}

/**
 * Locale translation adapter primitives for generated API docs.
 *
 * The default adapter is deterministic and keyless (safe for CI), while the adapter contract keeps
 * room for higher-quality engines later.
 */
import { spawn } from "node:child_process";
import {
  assertCleanMarkdownTranslation,
  buildBatchTranslationPrompt,
  buildMarkdownTranslationPrompt,
  extractJsonObject,
  preserveMarkdown,
  restoreMarkdown,
  stripMarkdownEnvelope,
} from "../../tools/translation-adapters/src/index.ts";
import { LOCALES } from "@pantoken/web-components";
import { GLOSSARY_TERMS, type GlossaryKind } from "./glossary.ts";
import { alignTrailingNewline, TranslationMemory } from "./translation-memory.ts";

// English display name per locale (e.g. "Hungarian (Magyar)" \u2192 the adapter prompt only needs the
// leading English name, not the native parenthetical), used to phrase the `AiTranslationAdapter`
// prompt for any target locale instead of a hardcoded "Hungarian". The three English regional variants
// are named explicitly instead — stripping their parenthetical would collapse all three (and root) to
// the bare word "English", losing the spelling/phrasing distinction (colour vs. color, etc.) the prompt
// needs to actually produce a localized (not identical) translation.
const ENGLISH_VARIANT_LABELS: Record<string, string> = {
  "en-AU": "Australian English",
  "en-CA": "Canadian English",
  "en-GB": "British English",
};

const LOCALE_LABELS: Record<string, string> = Object.fromEntries(
  Object.entries(LOCALES).map(([locale, meta]) => [
    locale,
    ENGLISH_VARIANT_LABELS[locale] ?? meta.label.replace(/\s*\(.*\)$/, ""),
  ]),
);

const spawnPrompt = (
  command: string,
  args: string[],
  prompt: string,
  context: string,
  timeoutMs: number,
): Promise<string> =>
  new Promise((resolve, reject) => {
    const child = spawn(command, args, { stdio: ["pipe", "pipe", "pipe"] });
    let output = "";
    let error = "";
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      reject(new Error(`AI command timed out after ${String(timeoutMs)}ms for ${context}`));
    }, timeoutMs);
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk) => {
      output += chunk;
    });
    child.stderr.on("data", (chunk) => {
      error += chunk;
    });
    child.on("error", (cause) => {
      clearTimeout(timer);
      reject(cause);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code !== 0) {
        reject(new Error(`AI command exited ${String(code)} for ${context}: ${error.trim()}`));
      } else {
        resolve(output.trimEnd());
      }
    });
    child.stdin.end(prompt);
  });

/** A pluggable translation engine: named, with markdown/text/batch translate methods. */
export interface TranslationAdapter {
  readonly name: string;
  /**
   * Whether this adapter produces real prose translations. The glossary sets this `false`: it only
   * knows structural terms, so the pipeline must not treat its passthrough of a prose block as a
   * translation (see the poison-cache guard in `translation-memory.ts`). Defaults to `true`.
   */
  readonly translatesProse?: boolean;
  translateMarkdown(input: string, filePath: string): Promise<string>;
  translateText(input: string): Promise<string>;
  /**
   * Translate many short strings in one request. Returns a map keyed by each item's `id`. Optional:
   * callers fall back to per-item {@link TranslationAdapter.translateText} when it's absent.
   *
   * `onChunk` (if given) is called with each chunk's partial results as it completes, so a caller can
   * persist and report progress mid-run rather than only after the whole batch returns. Chunks may
   * run concurrently, so `onChunk` can fire out of order.
   */
  translateBatch?(
    items: readonly { id: string; text: string }[],
    onChunk?: (partial: Record<string, string>) => void,
  ): Promise<Record<string, string>>;
}

/** Escape regex metacharacters so a glossary term can be dropped into a `RegExp` literally. */
const escapeRegExp = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** Build the match pattern for a glossary term, based on how it's shaped in generated markdown. */
const patternFor = (kind: GlossaryKind, term: string): RegExp => {
  const escaped = escapeRegExp(term);
  switch (kind) {
    case "heading":
      return new RegExp(`^(#{1,6} )${escaped}$`, "gm");
    case "line":
      return new RegExp(`^${escaped}$`, "g");
    case "badge":
      return new RegExp(`(pantoken-doc-tag">)${escaped}(<)`, "g");
    default:
      return new RegExp(`\\b${escaped}\\b`, "g");
  }
};

/** Build the replacement string for a translated term, preserving any capture groups `patternFor` used. */
const replacementFor = (kind: GlossaryKind, translated: string): string => {
  switch (kind) {
    case "heading":
      return `$1${translated}`;
    case "badge":
      return `$1${translated}$2`;
    default:
      return translated;
  }
};

/**
 * Deterministic adapter: substitutes known structural terms only (headings, badges, table labels),
 * looked up from the `<locale>/docs.api.po` catalog (see `glossary.ts` for the term list). It can't translate prose, so
 * `translatesProse` is `false`. Safe to run in CI — it never spawns an adapter or hits the network.
 */
export class GlossaryTranslationAdapter implements TranslationAdapter {
  readonly name = "glossary";
  // Deterministic term substitution only — it cannot translate prose, so the memory must never cache
  // its output under a prose key.
  readonly translatesProse = false;
  private readonly replacements: Array<[RegExp, string]>;

  constructor(locale = "hu") {
    const memory = TranslationMemory.load(locale, "api");
    // Untranslated terms are skipped (identity passthrough) rather than matched against an empty
    // string, so an in-progress locale still renders every OTHER already-translated term correctly.
    this.replacements = GLOSSARY_TERMS.flatMap(({ kind, term }) => {
      const translated = memory.get("text", term);
      if (translated === undefined) return [];
      return [[patternFor(kind, term), replacementFor(kind, translated)] as [RegExp, string]];
    });
  }

  translateMarkdown(input: string): Promise<string> {
    return Promise.resolve(translateWithoutFencedCode(input, (text) => this.translateSync(text)));
  }

  translateText(input: string): Promise<string> {
    return Promise.resolve(this.translateSync(input));
  }

  /** The deterministic core — synchronous; the async methods just wrap it to satisfy the contract. */
  private translateSync(input: string): string {
    const preserved = preservePackageNames(input);
    let out = preserved.text;
    for (const [pattern, value] of this.replacements) {
      out = out.replace(pattern, value);
    }
    return restorePackageNames(out, preserved.packageNames);
  }

  translateBatch(
    items: readonly { id: string; text: string }[],
    onChunk?: (partial: Record<string, string>) => void,
  ): Promise<Record<string, string>> {
    const out = Object.fromEntries(items.map((item) => [item.id, this.translateSync(item.text)]));
    onChunk?.(out);
    return Promise.resolve(out);

/**
 * Split generated API markdown into translatable segments.
 *
 * The locale pipeline used to hash and translate whole `.md` files. Generated docs churn on every
 * build (stability-badge flips, resolved token values, signature edits), so a whole-file key thrashed
 * and the page's prose reverted to English. This module cuts the file into blocks so only real prose
 * carries a content key — the scaffolding around it can change without busting the cache.
 *
 * Each segment is one of:
 * - `preserve` — emitted verbatim (non-HTML code fences, signatures, breadcrumbs, type/link-only lines, HTML).
 * - `html`     — an HTML fence whose visible text nodes translate while markup stays verbatim.
 * - `prompt` — a prompt fence whose body is translated while its fence markers stay intact.
 * - `glossary` — deterministic term substitution (section headings, stability-badge pills, table
 *   column labels). Cheap, keyless, never cached.
 * - `prose`    — real translation (descriptions, remarks, `@example` captions, table Description cells).
 * - `table`    — a GFM table parsed into a grid so header labels + Description cells translate while
 *   code columns and structure stay verbatim. Only emitted when the grid rebuilds byte-for-byte to the
 *   source (see the round-trip self-check); otherwise the table falls back to `preserve`.
 *
 * `reassemble(segmentMarkdown(md), (t) => t)` is the identity — the split is lossless.
 *
 * @module
 */

import {
  type DemoSegment,
  collectDemoUnits,
  reassembleDemoHtml,
  segmentDemoHtml,
} from "./segment-demo-html.ts";
import { resolveExampleTargets } from "@pantoken/utils/example-targets";

/** How a translatable segment is handled: cheap `glossary` substitution or real `prose` translation. */
export type TranslationKind = "glossary" | "prose";

/**
 * The marker `docs/scripts/build-css-api.ts` prepends to its JS Requirement/Enhancement callout
 * (`jsRequirementCallout`) — recognized here so the bold label and note translate instead of the
 * whole block being swallowed by the generic blockquote `preserve` rule below.
 */
export const JS_CALLOUT_MARKER = "<!-- js-requirement -->";

/** One block of split markdown, tagged by how it should be emitted or translated. */
export type Segment =
  | { kind: "preserve"; text: string }
  | { kind: "prompt"; opening: string; body: string; closing: string }
  | { kind: "html"; opening: string; body: DemoSegment[]; closing: string }
  /** The generated accessibility-audit table: visible text translates, markup and `<code>` stay. */
  | { kind: "audit"; body: DemoSegment[] }
  | { kind: "glossary"; text: string }
