function addStableThemeColorsAnchor(source: string, translated: string): string {
  const sourceHeadings = source.split("\n").filter((line) => /^## (?!#)/u.test(line));
  const targetIndex = sourceHeadings.indexOf("## Theme colors");
  const translatedLines = translated.split("\n");
  const translatedHeadingIndexes = translatedLines
    .map((line, index) => (/^## (?!#)/u.test(line) ? index : -1))
    .filter((index) => index >= 0);
  const headingLine = translatedHeadingIndexes[targetIndex];
  if (targetIndex < 0 || headingLine === undefined) {
    throw new Error("Could not locate the translated Theme colors heading");
  }

  translatedLines[headingLine] = translatedLines[headingLine]
    .replace(/\s+\{#[^}]+\}$/u, "")
    .concat(" {#theme-colors}");
  let output = translatedLines.join("\n");
  const previousHeadingLine = translatedHeadingIndexes[targetIndex - 1];
  const sectionStart =
    previousHeadingLine === undefined
      ? 0
      : translatedLines.slice(0, previousHeadingLine + 1).join("\n").length;
  const sectionEnd = translatedLines.slice(0, headingLine).join("\n").length;
  const translatedLinks = [...output.matchAll(/\]\(([^)]+)\)/gu)];
  const translatedLink = translatedLinks
    .filter(
      (match) =>
        match.index !== undefined && match.index > sectionStart && match.index < sectionEnd,
    )
    .at(-1);
  if (translatedLink?.index !== undefined) {
    const destinationStart = translatedLink.index + translatedLink[0].indexOf(translatedLink[1]!);
    output = `${output.slice(0, destinationStart)}#theme-colors${output.slice(destinationStart + translatedLink[1]!.length)}`;
  }
  return output;
}

/**
 * Gate for the compatibility manifest. Rebuilds the expected manifest in memory and fails if the
 * committed `compatibility.json` doesn't match — so an upstream bump or a new consumer must
 * regenerate it (`vp run sync:compatibility`) in the same change. Compares the *parsed* objects, so
 * it never fights the JSON formatter over whitespace.
 *
 * @module
 */
import fs from "node:fs/promises";
import path from "node:path";
import { buildCompatibility, type Compatibility } from "./compatibility.ts";

const ROOT = path.resolve(new URL("../../", import.meta.url).pathname);

/** Canonical (key-sorted) JSON, so equality ignores key order and whitespace. */
function canonical(value: unknown): string {
  const sort = (v: unknown): unknown => {
    if (v === null || typeof v !== "object") return v;
    if (Array.isArray(v)) return v.map(sort);
    const o = v as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(o)
        .sort()
        .map((k) => [k, sort(o[k])]),
    );
  };
  return JSON.stringify(sort(value));
}

async function main(): Promise<void> {
  const expected = await buildCompatibility();

  let committed: Compatibility | null = null;
  try {
    committed = JSON.parse(
      await fs.readFile(path.join(ROOT, "compatibility.json"), "utf8"),
    ) as Compatibility;
  } catch {
    committed = null;
  }

  if (!committed) {
    console.error(
      "✗ compatibility: compatibility.json is missing or unparseable. Run `vp run sync:compatibility` and commit it.",
    );
    process.exitCode = 1;
    return;
  }

  if (canonical(committed) !== canonical(expected)) {
    console.error(
      "✗ compatibility: compatibility.json is stale (upstream pins or consumers changed).",
    );
    console.error(
      "  Run `vp run sync:compatibility` and commit compatibility.json + docs/compatibility.md.",
    );
    process.exitCode = 1;
    return;
  }

  console.log(
    `✓ compatibility: manifest matches (${Object.keys(expected.upstream).length} upstream sources, ${expected.consumers.length} consumers).`,
  );
}

main().catch((error: unknown) => {
