          reference: relative(enApiDir, join(enApiDir, file)),
          flags: VERBATIM_API_PROSE.has(unit.text) ? [PANTOKEN_VERBATIM_FLAG] : [],
          translate: "always" as const,
        })),
    );
  const catalogPath = join(repoRoot, "l10n", "docs.api.pot");
  const catalog = serializePot(units, ["no-c-format"]);
  if (force) writeFileSync(catalogPath, catalog);
  else writeCatalog(catalogPath, catalog);
  refreshCoverageReports(join(repoRoot, "i18n.config.json"));
};

/** Verify that a translated guide retained the structural elements the writer depends on. */
export const preservesMarkdownStructure = (source: string, translated: string): boolean => {
  const count = (value: string, pattern: RegExp): number => value.match(pattern)?.length ?? 0;
  return (
    count(source, /^#{1,6}\s/gm) === count(translated, /^#{1,6}\s/gm) &&
    count(source, /^```/gm) === count(translated, /^```/gm) &&
    count(source, /^\|.*\|\s*$/gm) === count(translated, /^\|.*\|\s*$/gm)
  );
};

