 * auto-detected `component-capabilities.json` the CDN picker uses — the single source of truth for
 * whether a component needs `@pantoken/interactions`, so the docs badge can't drift from it.
 */
const capabilityByName = new Map(
  (capabilities.components as { name: string; type: string }[]).map((c) => [c.name, c.type]),
);

/** Render modifier names as inline code, joined "`a`, `b`, and `c`" / "`a` and `b`" / "`a`". */
function formatModifierList(names: readonly string[]): string {
  const code = names.map((n) => `\`${n}\``);
  if (code.length <= 1) return code.join("");
  if (code.length === 2) return `${code[0]} and ${code[1]}`;
  return `${code.slice(0, -1).join(", ")}, and ${code.at(-1)}`;
}

/**
 * The JS callout body: "JS Requirement" for `js-only` (no CSS at all — JS is mandatory) vs.
 * "JS Enhancement" for `both` (the CSS renders and works on its own; `@pantoken/interactions` only
 * adds the interactive behavior on top, it isn't required to use the component). `interactionModifiers`
 * are the record's `@modifier -x — @interaction …` entries — the specific script-toggled modifiers,
 * when any are documented, named here instead of leaving the reader to guess.
 */
function jsRequirementCallout(
  type: "js-only" | "both",
  interactionModifiers: readonly CssModifier[],
): string {
  const label = type === "js-only" ? "JS Requirement" : "JS Enhancement";
  const note =
    type === "js-only"
      ? "This component ships no CSS of its own — its markup and behavior come entirely from `@pantoken/interactions`."
      : "This component's CSS renders and works on its own; pair it with `@pantoken/interactions` to add the interactive behavior.";
  const plural = interactionModifiers.length > 1;
  const modifierNote = interactionModifiers.length
    ? ` Its ${formatModifierList(interactionModifiers.map((m) => m.name))} modifier${plural ? "s are" : " is"} driven by that behavior.`
    : "";
  return [
    JS_CALLOUT_MARKER,
    "> [!TIP]",
    `> **${label}** — ${note}${modifierNote} See the [modifier table below](#modifiers).`,
    "",
  ].join("\n");
}

import { globSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import {
  parsePo,
  serializePo,
  writeCatalog,
  type PoEntry,
} from "../../tools/i18n-engine/src/po.ts";
import {
  GENERATED_VALUES_MARKER,
  assertGeneratedTranslation,
  generatedMarkdown,
  migrateGeneratedMarkdown,
  restoreGeneratedMarkdown,
} from "../../tools/translation-adapters/src/generated-values.ts";
import { runAsMain } from "./cli.ts";
import { loadConfig } from "../../tools/i18n-engine/src/config.ts";
import { segmentMarkdown } from "../../docs/scripts/segment-markdown.ts";

/** Prepare one catalog migration atomically. Ambiguous values require a reviewed manual mapping. */
export function migrateGeneratedCatalog(
  entries: readonly PoEntry[],
  namespace: "api" | "guides",
  generatedTemplates?: ReadonlySet<string>,
): PoEntry[] {
  const output = new Map<string, PoEntry>();
  for (const entry of entries) {
    const compatibility = namespace === "guides" && entry.references.includes("compatibility.md");
    const apiTemplate =
      namespace === "api" && entry.msgctxt === "docs.api:prose"
        ? entry.msgid.includes("{{ptk_code_")
          ? entry.msgid
          : generatedMarkdown(entry.msgid).template
        : undefined;
    const eligible =
      !entry.obsolete &&
      (compatibility ||
        (apiTemplate !== undefined &&
          (generatedTemplates === undefined || generatedTemplates.has(apiTemplate))));
    let updated = entry;
    if (eligible) {
      try {
        const source = entry.msgid.replace(`${GENERATED_VALUES_MARKER}\n`, "");
        const options = compatibility ? { tables: true, tableValuesOnly: true } : {};
        if (source.includes("{{ptk_code_")) {
          assertGeneratedTranslation(
            source,
            entry.msgstr !== "" && !entry.fuzzy ? entry.msgstr : source,
          );
          updated = entry;
        } else {
          const generated = generatedMarkdown(source, options);
          const translation =
            entry.msgstr === "" || entry.fuzzy
              ? entry.msgstr
              : migrateGeneratedMarkdown(source, entry.msgstr, options);
          if (entry.msgstr !== "" && !entry.fuzzy) restoreGeneratedMarkdown(translation, generated);
          updated = { ...entry, msgid: generated.template, msgstr: translation };
        }
      } catch (error) {
        throw new Error(
          `${entry.references.join(", ")}: ${entry.msgid.slice(0, 100)}: ${String(error)}`,
          { cause: error },
        );
      }
    }
    const key = `${updated.obsolete}\0${updated.msgctxt ?? ""}\0${updated.msgid}`;
    const existing = output.get(key);
    if (existing && existing.msgstr !== updated.msgstr)
      throw new Error(`Conflicting translations for template: ${updated.msgid.slice(0, 100)}`);
    output.set(
      key,
      existing
        ? { ...existing, references: [...new Set([...existing.references, ...updated.references])] }
        : updated,
    );
  }
  return [...output.values()];
}

runAsMain(import.meta.url, async () => {
  const args = process.argv.slice(2);
  if (args.length > 1 || (args[0] !== "--check" && args[0] !== "--write"))
    throw new Error("Usage: migrate-generated-values.ts --check|--write");
  const l10n = join(import.meta.dirname, "../../l10n");
  const root = join(import.meta.dirname, "../..");
  const config = loadConfig(join(root, "i18n.config.json"));
  const generatedTemplates = new Set<string>();
  for (const file of globSync("docs/api/**/*.md", { cwd: root })) {
    for (const segment of segmentMarkdown(readFileSync(join(root, file), "utf8"))) {
      if (segment.kind === "callout")
        generatedTemplates.add(generatedMarkdown(segment.note).template);
      if (segment.kind === "prose" && segment.generatedValues)
        generatedTemplates.add(generatedMarkdown(segment.text).template);
    }
  }
  if (generatedTemplates.size === 0)
    throw new Error("Generate English API documentation before migrating value bindings");
  const pending: Array<{ path: string; catalog: string }> = [];
  const failures: string[] = [];
  const directories = [
    "",
    ...readdirSync(l10n, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && entry.name !== config.source)
      .map((entry) => entry.name),
  ];
  for (const directory of directories) {
    for (const namespace of ["api", "guides"] as const) {
      const path = join(l10n, directory, `docs.${namespace}.${directory ? "po" : "pot"}`);
      try {
        const source = readFileSync(path, "utf8");
        pending.push({
          path,
          catalog: serializePo(
            migrateGeneratedCatalog(parsePo(source), namespace, generatedTemplates),
          ),
        });
      } catch (error) {
        failures.push(`${path}: ${String(error)}`);
      }
    }
  }
  if (failures.length > 0) throw new Error(`No catalogs changed:\n${failures.join("\n")}`);
  if (args[0] === "--write") for (const file of pending) writeCatalog(file.path, file.catalog);
  console.log(
    `Generated-value migration: ${pending.length} catalogs ${args[0] === "--write" ? "written" : "validated"}`,
  );
});

