export function runRenderContent(
  config: I18nConfig,
  configDir: string,
  spaceId: string,
  locale: string,
): RenderResult {
  const space = config.spaces[spaceId];
  if (!space || space.kind !== "content") throw new Error(`"${spaceId}" is not a content space.`);
  const entries = loadPoEntriesForSpace(config, configDir, spaceId, locale);
  const byMsgid = new Map(
    entries.filter((e) => !e.obsolete && e.msgstr !== "").map((e) => [e.msgid, e.msgstr]),
  );
  const resolve = (text: string): string => byMsgid.get(text) ?? text;

  const filesWritten: string[] = [];
  for (const file of contentSpaceFiles(space, configDir)) {
    const rendered = renderContentFile(space.segment, file.source, resolve, locale);
    const outPath = join(
      configDir,
      resolvePattern(space.render, { locale, path: file.renderPath }),
    );
    mkdirSync(dirname(outPath), { recursive: true });
    writeFileSync(outPath, rendered);
    filesWritten.push(outPath);
  }
  cleanupStaleRenderedFiles(space, configDir, locale, new Set(filesWritten));
  return { space: spaceId, locale, filesWritten };
}

function cleanupStaleRenderedFiles(
  space: ContentSpaceConfig,
  configDir: string,
  locale: string,
  filesWritten: ReadonlySet<string>,
): void {
  if (space.transientRender || !space.render.includes("{path}")) return;
  const renderRoot = join(
    configDir,
    resolvePattern(space.render.slice(0, space.render.indexOf("{path}")), { locale }),
  );
  if (!existsSync(renderRoot)) return;
  for (const path of renderedFiles(renderRoot)) {
    if (!filesWritten.has(path)) rmSync(path, { force: true });
  }
}

function renderedFiles(root: string): string[] {
  return globSync("**/*", { cwd: root })
    .map((path) => join(root, path))
    .filter((path) => statSync(path).isFile());
}

