const isAsciiLetter = (char: string): boolean =>
  (char >= "A" && char <= "Z") || (char >= "a" && char <= "z");

const isIdentifierChar = (char: string): boolean =>
  isAsciiLetter(char) || (char >= "0" && char <= "9") || char === "_" || char === "$";

const isIdentifierSegmentChar = (char: string): boolean => isIdentifierChar(char) || char === "-";

const isIdentifierStart = (char: string): boolean =>
  isAsciiLetter(char) || char === "_" || char === "$";

const identifierEnd = (
  value: string,
  start: number,
  accepts: (char: string) => boolean,
): number => {
  let index = start;
  while (index < value.length && accepts(value[index])) index += 1;
  return index;
};

const isCodeShapedIdentifier = (value: string): boolean => {
  if (!isIdentifierStart(value[0])) return false;
  let index = identifierEnd(value, 1, isIdentifierChar);
  while ([".", "-"].includes(value[index])) {
    const segmentStart = index + 1;
    index = identifierEnd(value, segmentStart, isIdentifierSegmentChar);
    if (index === segmentStart) return false;
  }
  return /^(?:\(\))?\??$/u.test(value.slice(index));
};

/**
 * API identifiers, literal URLs, declarations, and other code-shaped fragments must remain English.
 * Mark them as required verbatim so the translation memory records the deliberate passthrough instead
 * of asking the model to translate them on every build.
 */
export const isRequiredVerbatimApiUnit = (source: string): boolean => {
  const text = source.trim();
  const withoutListMarker = text.replace(/^(?:-|\*)\s+/u, "");
  const unwrapped = withoutListMarker.replace(/^\*\*(.+)\*\*$/u, "$1");
  if (unwrapped === "Token") return true;
  if (/^(?:https?:\/\/|www\.)\S+$/iu.test(unwrapped)) return true;
  if (/^\*\*Source:\*\*\s+\[[^\]]+\]\(https?:\/\//u.test(text)) return true;
  if (/^@(?:import|supports|media|scope)\b/u.test(unwrapped)) return true;
  if (/^(?:--[a-z][\w-]*|[a-z-]+):\s*[^\n]+\.?$/iu.test(unwrapped)) return true;
  if (/^readonly\s+`[^`]+`(?:\[\])?$/u.test(unwrapped)) return true;

  return !GLOSSARY_TEXT.has(unwrapped) && isCodeShapedIdentifier(unwrapped);
};

const requiredVerbatimSources = (units: readonly TranslationUnit[]): ReadonlySet<string> =>
  new Set(
    units.filter(({ source }) => isRequiredVerbatimApiUnit(source)).map(({ source }) => source),
  );

const run = (command: string, args: string[]): void => {
  const result = spawnSync(command, args, {
    cwd: docsRoot,
    stdio: "inherit",
  });

  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(" ")} failed with exit code ${result.status ?? -1}`);
  }
};

